<?php
/**
 * POST /backend/api/auth/register.php
 * Body: { role: "buyer"|"farmer", name, mobile, email, password?, aadhaar? }
 *
 * 1. Checks duplicate email and mobile in users table.
 * 2. Checks email authenticity (RFC format, non-disposable domain, active MX).
 * 3. For buyers: auto-generates a secure login password.
 * 4. Staging: saves into pending_registrations (NOT users table).
 * 5. Sends verification email with auto-generated password and 6-digit OTP.
 */
require_once __DIR__ . '/../_bootstrap.php';
require_once __DIR__ . '/../../helpers/email_validator.php';
require_once __DIR__ . '/../../helpers/mailer.php';

if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_fail('POST required.', 405);

$body = json_body();
$role = $body['role'] ?? '';
$name = clean($body['name'] ?? '');
$mobile = clean($body['mobile'] ?? '');
$email = clean($body['email'] ?? '');
$password = (string)($body['password'] ?? '');
$aadhaar = clean($body['aadhaar'] ?? '');

// Basic field validations
if (!in_array($role, ['buyer', 'farmer'], true)) json_fail('Invalid registration role.');
if (!preg_match('/^[A-Za-z ]+$/', $name)) json_fail('Name should contain letters only.');
if (!preg_match('/^[0-9]{10}$/', $mobile)) json_fail('Enter a valid 10-digit mobile number.');

// 1 & 2. Authenticity & Duplicate Checks (scoped by role so a user can register as both farmer and buyer with the same Gmail)
$emailCheck = validate_email_authenticity($email, $conn, null, $role);
if (!$emailCheck['ok']) {
    json_fail($emailCheck['error'], $emailCheck['is_duplicate'] ? 409 : 400);
}

$mobileCheck = validate_mobile_uniqueness($mobile, $conn, null, $role);
if (!$mobileCheck['ok']) {
    json_fail($mobileCheck['error'], $mobileCheck['is_duplicate'] ? 409 : 400);
}

// Aadhaar check for farmers
if ($role === 'farmer') {
    $cleanAadhaar = preg_replace('/\s+/', '', $aadhaar);
    if (strlen($cleanAadhaar) !== 12 || !ctype_digit($cleanAadhaar)) {
        json_fail('Enter a valid 12-digit Aadhaar number.');
    }
}

// 4. Auto-generate password for buyers & farmers
$autoGeneratedPassword = null;
if (!empty($password) && strlen($password) >= 6) {
    // User typed their own password
    $passwordToUse = $password;
    $autoGeneratedPassword = $password;
} else {
    // Auto-generate secure 8-character password: 2 uppercase, 3 lowercase, 2 digits, 1 special symbol
    $lettersU = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
    $lettersL = 'abcdefghjkmnpqrstuvwxyz';
    $digits   = '23456789';
    $specials = '!@#$%&*';
    
    $pwdChars = [
        $lettersU[random_int(0, strlen($lettersU) - 1)],
        $lettersU[random_int(0, strlen($lettersU) - 1)],
        $lettersL[random_int(0, strlen($lettersL) - 1)],
        $lettersL[random_int(0, strlen($lettersL) - 1)],
        $lettersL[random_int(0, strlen($lettersL) - 1)],
        $digits[random_int(0, strlen($digits) - 1)],
        $digits[random_int(0, strlen($digits) - 1)],
        $specials[random_int(0, strlen($specials) - 1)],
    ];
    shuffle($pwdChars);
    $autoGeneratedPassword = implode('', $pwdChars);
    $passwordToUse = $autoGeneratedPassword;
}

$hash = password_hash($passwordToUse, PASSWORD_DEFAULT);

// Generate 32-byte verification token & 6-digit numeric OTP code
$token = bin2hex(random_bytes(24));
$otpCode = str_pad((string)random_int(100000, 999999), 6, '0', STR_PAD_LEFT);
$expiresAt = date('Y-m-d H:i:s', time() + 86400); // 24 hours

// 5. STAGING ONLY: Store in pending_registrations table (NOT users table!)
// Remove any previous pending registration for this email/mobile so user can restart cleanly
$delPending = mysqli_prepare($conn, "DELETE FROM pending_registrations WHERE LOWER(email) = LOWER(?) OR mobile = ?");
mysqli_stmt_bind_param($delPending, "ss", $email, $mobile);
mysqli_stmt_execute($delPending);

$aadhaarVal = ($role === 'farmer') ? preg_replace('/\s+/', '', $aadhaar) : null;

$insertPending = mysqli_prepare($conn, "
    INSERT INTO pending_registrations (name, mobile, email, password_hash, auto_password, role, aadhaar, token, otp_code, status, expires_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?)
");
mysqli_stmt_bind_param(
    $insertPending,
    "ssssssssss",
    $name,
    $mobile,
    $email,
    $hash,
    $autoGeneratedPassword,
    $role,
    $aadhaarVal,
    $token,
    $otpCode,
    $expiresAt
);
mysqli_stmt_execute($insertPending);
$pendingId = mysqli_insert_id($conn);

if ($pendingId <= 0) {
    json_fail('Failed to stage registration. Please try again.', 500);
}

// 4. Send Gmail verification email with auto-generated password attached
if ($role === 'buyer') {
    send_buyer_verification_mail($email, $name, $passwordToUse, $token, $otpCode);
} else {
    send_farmer_verification_mail($email, $name, $passwordToUse, $token, $otpCode);
}

$_SESSION['pending_registration_id'] = $pendingId;
$_SESSION['pending_email'] = $email;
$_SESSION['pending_token'] = $token;

json_ok([
    'registered_pending' => true,
    'email' => $email,
    'mobile' => $mobile,
    'role' => $role,
    'auto_password_sent' => true,
    'dev_otp' => $otpCode,                      // For development convenience
    'dev_token' => $token,
    'message' => 'Verification code & login password sent to your Gmail. Please check your inbox.',
]);
